import java.util.*;
abstract class Question {String id,text;int points;Question(String i,String t,int p){id=i;text=t;points=p;}abstract boolean evaluate(String answer);}
class MultipleChoiceQuestion extends Question {String correct;MultipleChoiceQuestion(String i,String t,int p,String c){super(i,t,p);correct=c;}boolean evaluate(String a){return correct.equalsIgnoreCase(a);}}
class TrueFalseQuestion extends Question {boolean correct;TrueFalseQuestion(String i,String t,int p,boolean c){super(i,t,p);correct=c;}boolean evaluate(String a){return Boolean.toString(correct).equalsIgnoreCase(a);}}
class ShortAnswerQuestion extends Question {String correct;ShortAnswerQuestion(String i,String t,int p,String c){super(i,t,p);correct=c;}boolean evaluate(String a){return correct.equalsIgnoreCase(a.trim());}}
class Examination {String title;List<Question> questions;Examination(String t,Question...q){title=t;questions=Arrays.asList(q);}}
class Attempt {Examination exam;Map<String,String> answers=new HashMap<>();boolean submitted;Attempt(Examination e){exam=e;}void answer(String id,String a){if(submitted)throw new IllegalStateException("Cannot change answers for a submitted examination");answers.put(id,a);}String submit(){if(submitted)throw new IllegalStateException();submitted=true;int score=0,max=0;StringBuilder b=new StringBuilder();for(Question q:exam.questions){max+=q.points;boolean ok=q.evaluate(answers.getOrDefault(q.id,""));if(ok)score+=q.points;if(b.length()>0)b.append(", ");b.append(q.id).append(": ").append(ok?"Correct":"Incorrect").append(" (").append(ok?q.points:0).append(" points)");}return b+" Total score: "+score+"/"+max;}}
public class Problem3_OnlineExaminationSystem {public static void main(String[]x){Examination e=new Examination("Exam A",new MultipleChoiceQuestion("Question 1","Pick",5,"C"),new TrueFalseQuestion("Question 2","True?",5,false));Attempt a=new Attempt(e);a.answer("Question 1","C");a.answer("Question 2","True");System.out.println(a.submit());try{a.answer("Question 1","A");}catch(Exception ex){System.out.println(ex.getMessage());}}}